class _TTLCache(LinkedDict):
    """Internal cache implementation."""

    def __init__(self, maxsize, ttl, timer, typed=False):
        self._maxsize = maxsize
        self._ttl = ttl
        self._timer = timer
        self._typed = typed

    def get(self, func, *args, **kwargs):
        key = hashkey(args, kwargs) if self._typed else id(args[0])
        if key in self:
            value, expires_at = self[key]
            if self._timer() < expires_at:
                return value
        value = func(*args, **kwargs)
        self[key] = (value, self._timer() + self._ttl)
        return value
