def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hints = {}
        locks = {}
        root = []
        make_key = func.cache_info().make_key
        kwd_mark = object()

        def wrapper(*args, **kwd):
            key = make_key(args, kwd, typed)
            now = timer()

            # check cache and TTL validity
            if key in cache and cache[key][1] + ttl >= now:
                return cache[key]

            # update LRU order
            if key in cache:
                hints.pop(key)
                cache[key][1] = now
                locks[key].release()
            else:
                cache[key] = func(*args, **kwd), now
                locks[key] = threading.Lock()
                root.append(key)
                hints[key] = 0
                locks[key].acquire()

                # maintain LRU order
                if len(root) > maxsize:
                    for i in range(maxsize // 4, maxsize // 2):
                        if locks[root[-i]].acquire(0):
                            del root[-i]
                            del cache[root[-i]]
                            del hints[root[-i]]
                            del locks[root[-i]]
                            return wrapper(*args, **kwd)

            # enforce TTL
