def generate_default_observer_schema_for_resource(res):
    """Generate the default observer schema for a Kubernetes resource.

    Args:
        res (krake.data.kubernetes.KubernetesResource): The Kubernetes resource for which to generate a
            default observer schema
    """
    schema = {
        "name": res.name,
        "kind": "resource",
        "resources": [
            {
                "name": res.name,
                "kind": res.kind
            }
        ]
    }
    return schema

