def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Validation for a valid inventory starts here
    # Check for a type value if extract_spec_version is True
    if extract_spec_version:
        if 'type' in inventory and isinstance(inventory['type'], str):
            spec_version = inventory['type']
        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version
    # Check that the spec_version is valid
    if not isinstance(spec_version, str):
        raise ValueError("Invalid specification version: expected str but got %s" %
                         type(spec_version).__name__)
    # Check that the spec_version is one of the accepted values
    if spec_version not in self.accepted_specifications:
        raise ValueError("Invalid specification version: expected one of %s but got %s" %
                         (', '.join(self.accepted_specifications), spec_version))
    # Check for the required elements for the spec_version
    for element in self.required_elements[spec_version]:
        if element not in inventory:
            raise ValueError("Required element '%s' missing from inventory for specification version %s" % (element, spec_version))
    # Check for the allowed elements for the spec_version
    for element in inventory:
        if element not in self.allowed_elements[spec_version]:
            raise ValueError("Element '%s' is not allowed in inventory for specification version %s" % (element, spec_version))
    # Validation for a valid inventory ends here
    return True

