def validate_as_prior_version(self, prior):
    # Check that the input variable prior is an InventoryValidator object
    assert isinstance(prior, InventoryValidator)

    # Check that both self and prior inventories are valid
    assert self.is_valid() and prior.is_valid()

    # Check that self has no changes since version prior
    if self.version > prior.version:
        raise InventoryValidationError("Inventory version does not follow the proper sequence")

    # Check that all entities in self exist in prior
    for entity in self.entities:
        if not prior.contains_entity(entity):
            raise InventoryValidationError("Entity " + entity + " does not exist in prior version")

        # Check that all attributes of entity in self exist in prior
        for attr in entity.attributes:
            if not prior.entity_has_attribute(entity, attr):
                raise InventoryValidationError("Attribute " + attr + " of entity " + entity + " does not exist in prior version")

            # Check that the values of attr in self match the values of attr in prior
            self_value = entity.attr_value(attr)
            prior_value = prior.entity_attr_value(entity, attr)
            if self_value != prior_value:
                raise InventoryValidationError("Value of attribute " + attr + " of entity " + entity + " does not match prior version")

