        self.comment = comment
        self.icon = icon, "icon",
        self.hints = hints

    def is_valid_file(self, context, path):
        """Checks whether a path (file or directory) is valid for this type.

        Args:
            context: The context the type is being used in
            path: A path (file or directory) to check
        Returns:
            True if the path (file or directory) is valid for this type.
        """
        if self.filename_validator(path, context):
            if not os.path.exists(path):
                return False
            return True
        try:
            is_dir = os.path.isdir(path)
        except:
            return False
        return not is_dir

    def is_valid_file_name(self, context, name):
        """Check whether a file name is valid for this type.

        Args:
            context: The context the type is being used in
            path: A file name to check
        Returns:
            True if the file name is valid for this type.
        """
        return self.filename_validator.is_valid_name(context, name)

