        file_path = file_path.strip()

        if file_path.endswith("_asset.cam"):
            package_type = "asset"
        elif file_path.endswith("_render.cam"):
            package_type = "rendition"
        else:
            raise ValueError(f"Invalid package type: {file_path}")

        package_name = prefix + "." + package_type

        package = {"type": package_type, "path": file_path}
        packages.append(package)

        return package

