def make_parsers():
    """
    Build a top-level parser and its subparsers and return them as a tuple.
    """

    parsers = {}
    subparsers = {}

    for class_name in get_parsable_classes():
        parser = get_parser_for_class(class_name)
        parser.set_defaults(func=invoke_parsable_class, class_name=class_name)
        parsers[class_name] = parser

        subparser = parser.add_subparsers()
        for subclass_name in get_subclasses(class_name):
            subparser_for_subclass = get_parser_for_subclass(subclass_name, class_name)
            subparser.add_parser(subclass_name, help=subclass_name)
            subparsers[subclass_name] = subparser_for_subclass

    return parsers, subparsers

