def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Load and validate each configuration file. Return a tuple if the parsed configuration and a 
    sequence of log records containing any parse errors.
    Args:
        config_filenames (list): Configuration filenames.
        overrides (dict): Configuration overrides, or None.
