    if scale not in (None, True):
        raise ValueError("scale must be None or True")

    if scale is True and not hist.has_scale:
        raise ValueError("histogram must have a scale")

    if make_value is None:
        make_value = lambda bin_: bin_.content
    elif not callable(make_value):
        raise ValueError("make_value must be a callable function")

