def verify_morrisons(hash, key, algorithm=sha256):
    """Verify that a hash value is valid for the given key and algorithm.

    Arguments:
        hash (str): The stored hash value
        key (str): The secret key
        algorithm (str): The hash algorithm to use, e.g. sha256 or sha512

    Returns:
