def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone,
    calculates a timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """

    if not isinstance(dt, datetime):
        raise TypeError("The 'dt' argument must be a datetime object.")

    if not hasattr(dt, "tzinfo"):
        raise ValueError("The 'dt' argument must be a timezone-aware datetime object.")

    if dt.tzinfo is None:
        raise ValueError("The 'dt' argument must be a timezone-aware datetime object.")

    if not isinstance(dt.tzinfo, tzinfo):
        raise ValueError("The 'dt.tzinfo' attribute must be a tzinfo object.")

    new_tzinfo = self.tzinfo

    if new_tzinfo is None:
        raise ValueError("The 'tzinfo' attribute of the 'self' object must be a tzinfo object.")

    if isinstance(new_tzinfo, tzinfo):
        raise ValueError("The 'new_tzinfo' argument must be a tzinfo object.")

    if not isinstance(new_tzinfo, tzinfo):
        raise ValueError("The 'new_tzinfo' argument must be a tzinfo object.")

    if new_tzinfo.utcoffset(dt) is None:
        raise ValueError("The 'utcoffset' method of the 'new_tzinfo' argument must not return None.")

    if new_tzinfo.dst(dt) is None:
        raise ValueError("The 'dst' method of the 'new_tzinfo' argument must not return None.")

    if type(new_tzinfo.utcoffset(dt)) is not timedelta:
        raise TypeError("The 'utcoffset' method of the 'new_tzinfo' argument must return a timedelta object.")

    if type(new_tzinfo.dst(dt)) is not timedelta:
        raise TypeError("The 'dst' method of the 'new_tzinfo' argument must return a timedelta object.")

    new_dt = dt + new_tzinfo.utcoffset(dt) + new_tzinfo.dst(dt)

    return new_dt
