def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    pattern = r"\[[^[]*?\]\[[^\[\]]*?\]\s*|TAG: [^\n]*"
    matches = re.finditer(pattern, text, re.DOTALL | re.MULTILINE)

    for match in matches:
        tag = match.group(0).strip()

        # remove tags inside code blocks
        if tag.startswith("[["):
            continue

        # remove leading "TAG: " from the tag text
        if tag.startswith("TAG: "):
            tag = tag[5:]

        tags.add(tag)

    if replacer:
        return (tags, " ".join(replacer(tag) for tag in tags) + text)
    else:
        return (tags, text)

