def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    # Validate arguments
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("Invalid URL. Please provide a valid URL with protocol, ie https://example.com")

    if document_path is not None and not document_path.startswith("/"):
        raise ValueError("Invalid document_path. Please provide a valid document path if supplied, ie /docs/nodeinfo")

    # Generate the JSON-LD NodeInfo document
    nodeinfo_document = {
        "@context": "https://nodeinfo.diaspora.software/ns/combined",
        "type": "NodeInfo",
        "name": "example",
        "version": "1.2",
        "protocols": {
            "web": [
                {"network": "http", "version": "1.0"},
