    if not doc or not isinstance(doc, Document):
        raise ValueError("Invalid document")

    # Verify that the provided signature is not None or empty
    if not signature or not isinstance(signature, bytes):
        raise ValueError("Invalid signature")

    # Verify that the signed elements are not None or empty
    signed_xml_elements = doc.find_elements("versions/signed/signed-elements")
    if not signed_xml_elements or not isinstance(signed_xml_elements, list):
