def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if isinstance(document, str):
        if document.startswith('{') and document.endswith('}'):
            return json.loads(document)
        elif document.startswith('<') and document.endswith('>'):
            soup = BeautifulSoup(document, 'lxml')
            return {
                'subject': soup.find('subject').text,
                'aliases': [alias.text for alias in soup.find_all('alias')],
                'properties': {property.name: property.attrib['action'] for property in soup.find_all('property')}
            }
        else:
            raise ValueError('Invalid Diaspora webfinger format')
    else:
        raise TypeError('document must be a string')
