def flatten_dict(d):
    flat_dict = {}
    def recurse(d, parent_key=''):
        for k, v in d.items():
            new_key = parent_key + '.' + k if parent_key else k
            if isinstance(v, dict):
                recurse(v, new_key)
            else:
                flat_dict[new_key] = v
    recurse(d)
    return flat_dict
